{
  "watch1": {
    "scenarios": [
      "features/creating-todos.feature:A new todo is created when the user presses Enter with non-empty text",
      "features/creating-todos.feature:A new todo is not created when the user presses Enter with empty text",
      "features/creating-todos.feature:A new todo is not created when the user presses Enter with whitespace only",
      "features/creating-todos.feature:The new todo input is trimmed before creating",
      "features/creating-todos.feature:Multiple todos can be created sequentially"
    ]
  },
  "watch2": {
    "scenarios": [
      "features/toggling-todos.feature:Clicking the checkbox marks a todo as completed",
      "features/toggling-todos.feature:Clicking the checkbox on a completed todo marks it as active",
      "features/toggling-todos.feature:The completed class is toggled on the todo item"
    ]
  },
  "watch3": {
    "scenarios": [
      "features/mark-all-complete.feature:The toggle-all checkbox marks all todos as completed",
      "features/mark-all-complete.feature:The toggle-all checkbox marks all todos as active",
      "features/mark-all-complete.feature:The toggle-all checkbox reflects the state of all todos"
    ]
  },
  "watch4": {
    "scenarios": [
      "features/editing-todos.feature:Double-clicking a todo activates editing mode",
      "features/editing-todos.feature:Pressing Enter saves the edit and exits editing mode",
      "features/editing-todos.feature:Blurring the edit input saves the edit",
      "features/editing-todos.feature:Pressing Escape discards the edit",
      "features/editing-todos.feature:Saving an empty edit deletes the todo",
      "features/editing-todos.feature:Saving a whitespace-only edit deletes the todo"
    ]
  },
  "watch5": {
    "scenarios": [
      "features/deleting-todos.feature:Clicking the destroy button removes a todo",
      "features/deleting-todos.feature:Deleting a todo does not affect other todos"
    ]
  },
  "watch6": {
    "scenarios": [
      "features/clear-completed.feature:Clear completed removes all completed todos",
      "features/clear-completed.feature:Clear completed is hidden when there are no completed todos",
      "features/clear-completed.feature:Clear completed is visible when there are completed todos"
    ]
  },
  "watch7": {
    "scenarios": [
      "features/counter.feature:The counter shows zero items when there are no todos",
      "features/counter.feature:The counter shows the number of active todos",
      "features/counter.feature:The counter uses singular form for one item",
      "features/counter.feature:The counter uses plural form for multiple items"
    ]
  },
  "watch8": {
    "scenarios": [
      "features/filtering.feature:All todos are shown by default",
      "features/filtering.feature:The Active filter shows only incomplete todos",
      "features/filtering.feature:The Completed filter shows only completed todos",
      "features/filtering.feature:The filter is applied when navigating via hash",
      "features/filtering.feature:A todo updated while filtered is hidden if it no longer matches"
    ]
  },
  "watch9": {
    "scenarios": [
      "features/persistence.feature:Todos are saved to localStorage",
      "features/persistence.feature:Completed state is persisted",
      "features/persistence.feature:The localStorage key is \"todos-todomvc\""
    ]
  },
  "watch10": {
    "scenarios": [
      "features/visibility.feature:The main section and footer are hidden when there are no todos",
      "features/visibility.feature:The main section and footer are shown when there are todos",
      "features/visibility.feature:The main section and footer are hidden after all todos are deleted"
    ]
  }
}

